class Solution {
    public String pushDominoes(String dominoes){
        int n=dominoes.length(),force=0;
        int[] forces=new int[n];
        for(int i=0;i<n;i++){
            char c=dominoes.charAt(i);
            force=c=='R'?n:c=='L'?0:Math.max(force-1,0);
            forces[i]+=force;
        }
        force=0;
        for(int i=n-1;i>=0;i--){
            char c=dominoes.charAt(i);
            force=c=='L'?n:c=='R'?0:Math.max(force-1,0);
            forces[i]-=force;
        }
        StringBuilder answer=new StringBuilder();
        for(int value:forces)answer.append(value>0?'R':value<0?'L':'.');
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun pushDominoes(dominoes:String):String{
        val n=dominoes.length;
        val forces=IntArray(n);
        var force=0;
        for(i in 0 until n){
            force=when(dominoes[i]){
                'R'->n;
                'L'->0;
                else->maxOf(force-1,0)
            };
            forces[i]+=force
        };
        force=0;
        for(i in n-1 downTo 0){
            force=when(dominoes[i]){
                'L'->n;
                'R'->0;
                else->maxOf(force-1,0)
            };
            forces[i]-=force
        };
        return buildString{
            for(value in forces)append(if(value>0)'R' else if(value<0)'L' else '.')
        }
    }
}

